-- Abu Dhabi Client Tracker — Supabase Schema
-- Run this entire file in the Supabase SQL Editor

CREATE TABLE IF NOT EXISTS companies (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT,
  address TEXT,
  website TEXT,
  maps TEXT,
  procurement_email TEXT,
  office_phone TEXT,
  procurement_officer TEXT,
  notes TEXT,
  physical_meeting_1 BOOLEAN DEFAULT FALSE,
  call_1 BOOLEAN DEFAULT FALSE,
  call_2 BOOLEAN DEFAULT FALSE,
  call_3 BOOLEAN DEFAULT FALSE,
  physical_meeting_2 BOOLEAN DEFAULT FALSE,
  status TEXT,
  assigned_to TEXT,
  added_date DATE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS pending_companies (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT,
  city TEXT,
  address TEXT,
  website TEXT,
  maps TEXT,
  procurement_email TEXT,
  office_phone TEXT,
  procurement_officer TEXT,
  notes TEXT,
  added_date DATE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS app_settings (
  key TEXT PRIMARY KEY,
  value TEXT
);

-- Disable RLS for simplicity (protected by password gate in frontend)
ALTER TABLE companies DISABLE ROW LEVEL SECURITY;
ALTER TABLE pending_companies DISABLE ROW LEVEL SECURITY;
ALTER TABLE app_settings DISABLE ROW LEVEL SECURITY;

